	'messages:apihelp-checktoken-summary' => 'de:Überprüft die Gültigkeit eines über <kbd>[[Special:ApiHelp/query+tokens|action=query&meta=tokens]]</kbd> erhaltenen Tokens.',
	'messages:apihelp-checktoken-param-type' => 'de:Typ des Tokens, das getestet werden soll.',
